#!/usr/bin/env node
// Validate a skill generated by vajra and optionally render its workflow graph.
//
// Usage:
//   node validate.mjs <skill-dir> [--project <root>] [--mermaid] [--write-graph] [--json]
//   node validate.mjs --version
//
//   --project      also check that <root>/.flow/<skill>/project.md (or the .md file given) binds
//                  every name in the skill's bindings.md
//   --mermaid      print the workflow graph as a Mermaid flowchart
//   --write-graph  write <skill-dir>/graph.md (Mermaid + node table); skipped when there are errors
//   --json         print the result as JSON
//
// Exit code 0 when there are no errors (warnings allowed), 1 otherwise.
// No dependencies: Node 18+ only.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const VERSION = "0.3.0";
// Version of the file contract (playbook frontmatter, profile frontmatter). Bump on breaking changes
// and document the migration in references/graph-model.md#schema-versions.
export const SCHEMA = 2;

const PHASES = ["explore", "expand", "extract", "any"];
const LIFECYCLES = ["throwaway", "tracer", "hardened", "any"];
const KINDS = ["work", "gate", "service"];
export const ENUMS = { phase: PHASES, lifecycle: LIFECYCLES, kind: KINDS };
const LIFECYCLE_RANK = { throwaway: 0, tracer: 1, hardened: 2 };
const RANK_NAME = ["throwaway", "tracer", "hardened"];
const PLAYBOOK_KEYS = ["id", "title", "phase", "lifecycle", "kind", "promotes", "terminal", "exits", "checks", "writes", "irreversible"];
const REQUIRED_SECTIONS = ["Purpose", "Steps", "Done when"];
const NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
// SKILL.md frontmatter fields allowed by the Agent Skills specification.
export const SKILL_FIELDS = ["name", "description", "license", "compatibility", "metadata", "allowed-tools"];
const PROMOTES_RE = /^(throwaway|tracer|hardened)\s*->\s*(throwaway|tracer|hardened)$/;

// Cross-cutting domain traits; see references/facets/. Each one changes evidence, gates or rails.
export const FACETS = [
  "measured-outcome", "perceptual-output", "data-dependence", "stand-in-ladder", "physical-world",
  "shared-contracts", "data-mutation", "external-release", "resource-budgets", "reproducibility",
];
export const RAILS = ["advisory", "standard", "strict"];

// Profile axes stored in profile.md frontmatter. Free-form axes (domains) are checked for shape only.
export const PROFILE_AXES = {
  uncertainty: ["clear", "complicated", "complex", "chaotic"],
  requirements: ["fixed", "shifting", "unknown"],
  journey: ["explore", "expand", "extract"],
  failure_cost: ["throwaway", "internal", "customer", "regulated"],
  artifact_lifetime: ["disposable", "evolving", "long-lived"],
  cadence: ["continuous", "timeboxed", "phase-gated"],
  team: ["solo", "small", "multi-team"],
  verification: ["evidence", "test-after", "tdd", "formal"],
  autonomy: ["high", "medium", "low"],
  parallelism: ["none", "explore-only", "wherever-splittable"],
  domains: null,
  facets: FACETS,
  hardware: ["none", "simulated", "attached", "custom-hardware"],
  invocation: ["explicit", "auto"],
  rails: RAILS,
};
const LIST_AXES = new Set(["journey", "domains", "facets"]);

// ---------- shared matching helpers (also used by flow.mjs) ----------
// Command patterns: "/regex/flags" is a regular expression, anything else matches as a substring
// of the whitespace-normalized command.
export function commandMatches(pattern, command) {
  const cmd = String(command).replace(/\s+/g, " ").trim();
  const re = pattern.match(/^\/(.+)\/([a-z]*)$/);
  return re ? new RegExp(re[1], re[2]).test(cmd) : cmd.includes(pattern.replace(/\s+/g, " ").trim());
}

// ---------- shell commands (flow.mjs checks guards and the run state against these) ----------
// A small reader for POSIX shells and PowerShell: splits a command line into the simple commands
// it would run, with their words unquoted. Text that is only data (quoted arguments, comments,
// heredoc bodies) stays inside one word or is dropped, while code the shell would run from inside
// it is read as commands of its own: $(...), `...` and <(...); the script of `sh -c`, `eval`,
// `ssh`, `watch`, `pwsh -Command`, `pwsh -EncodedCommand`, `cmd /c`, `Invoke-Expression` and
// `Start-Process`; and heredocs or pipes that feed a shell its script on stdin.
// Each command is an array of { text, quoted, redir } words; `ps` on the array marks PowerShell.
const SHELLS = new Set(["sh", "bash", "zsh", "dash", "ksh", "fish", "su"]);
const POWERSHELLS = new Set(["pwsh", "powershell"]);
const WRAPPERS = new Set(["sudo", "env", "exec", "nohup", "command", "time", "nice", "doas", "&", "."]);
const KEYWORDS = new Set(["if", "then", "else", "elif", "do", "while", "until", "!", "{", "}", "time"]);
// Past these limits a line is not read further but refused as too complex: scripts nested deeper
// than MAX_DEPTH would otherwise go unchecked, and a line built to multiply the work (`ssh ssh ...`)
// would run the hook into its timeout, which most agents treat as "allow".
const MAX_DEPTH = 8;
const MAX_READS = 500;
const MAX_CHARS = 4_000_000;
export class TooComplex extends Error {}

// The program a word names, as the shell would look it up: no directory, no .exe, any case.
export const programName = (t) => t.replace(/\\/g, "/").split("/").pop().toLowerCase().replace(/\.exe$/, "");

// Index of the first word that is the program itself, past assignments and wrappers like sudo.
export function commandStart(w) {
  let k = 0;
  while (k < w.length - 1 && (/^\w+=/.test(w[k].text) || (k > 0 && /^-/.test(w[k].text)) || WRAPPERS.has(programName(w[k].text)))) k++;
  return k;
}

function closing(s, i, open, close, esc) {
  // i is just past `open`; returns the index of the matching `close`, skipping quotes and escapes.
  for (let depth = 1; i < s.length; i++) {
    const c = s[i];
    if (c === esc) i++;
    else if (c === "'") { i = s.indexOf("'", i + 1); if (i < 0) break; }
    else if (c === '"') { for (i++; i < s.length && s[i] !== '"'; i++) if (s[i] === esc) i++; }
    else if (c === open) depth++;
    else if (c === close && --depth === 0) return i;
  }
  throw new Error("unclosed " + open);
}

// Commands substituted inside double quotes, here-strings or an unquoted heredoc body.
function substitutions(s, nested, ps) {
  const esc = ps ? "`" : "\\";
  for (let i = 0; i < s.length; i++) {
    if (s[i] === esc) i++;
    else if (s[i] === "$" && s[i + 1] === "(") { const e = closing(s, i + 2, "(", ")", esc); nested.push({ text: s.slice(i + 2, e), ps }); i = e; }
    else if (!ps && s[i] === "`") { const e = s.indexOf("`", i + 1); if (e < 0) throw new Error("unclosed `"); nested.push({ text: s.slice(i + 1, e), ps }); i = e; }
  }
}

function decodeEncodedCommand(b64) {
  try { return Buffer.from(b64, "base64").toString("utf16le"); } catch { return ""; }
}

function tokenize(s, ps, nested, bodies) {
  const cmds = [], heredocs = [];
  let words = [], word = null, redir = false, piped = false;
  const flush = () => { if (word) { words.push(word); word = null; } };
  const end = (pipe = false) => { flush(); if (words.length) { words.piped = piped; cmds.push(words); } words = []; redir = false; piped = pipe; };
  const add = (t, quoted) => { word ||= { text: "", quoted: false, redir }; word.text += t; word.quoted ||= quoted; redir = false; };
  const esc = ps ? "`" : "\\";
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === "\r") continue;
    if (c === "\n") {
      end();
      for (const h of heredocs) {
        const lines = [];
        let j = i + 1;
        for (;;) {
          const nl = s.indexOf("\n", j), line = s.slice(j, nl < 0 ? s.length : nl).replace(/\r$/, "");
          j = nl < 0 ? s.length : nl + 1;
          if ((h.tabs ? line.replace(/^\t+/, "") : line) === h.delim) break;
          lines.push(line);
          if (nl < 0) break;
        }
        bodies.push(lines.join("\n"));
        if (!h.quoted) substitutions(bodies[bodies.length - 1], nested, false);
        i = j - 1;
      }
      heredocs.length = 0;
    } else if (c === " " || c === "\t") flush();
    else if (ps && c === "<" && s[i + 1] === "#") { const e = s.indexOf("#>", i + 2); if (e < 0) throw new Error("unclosed <#"); i = e + 1; }
    else if (c === "#" && !word) { const nl = s.indexOf("\n", i); i = (nl < 0 ? s.length : nl) - 1; }
    else if (c === esc) { if (s[i + 1] !== "\n") add(s[i + 1] ?? "", false); i++; }
    else if (ps && c === "@" && (s[i + 1] === '"' || s[i + 1] === "'") && /^\r?\n/.test(s.slice(i + 2))) {
      // PowerShell here-string: data up to a line that starts with "@ or '@.
      const q = s[i + 1], e = s.indexOf(`\n${q}@`, i + 2);
      if (e < 0) throw new Error("unclosed here-string");
      const t = s.slice(s.indexOf("\n", i) + 1, e).replace(/\r$/, "");
      if (q === '"') substitutions(t, nested, true);
      add(t, true); i = e + 2;
    } else if (c === "'") {
      let t = "", j = i + 1;
      for (;; j++) {
        const e = s.indexOf("'", j);
        if (e < 0) throw new Error("unclosed '");
        t += s.slice(j, e);
        if (ps && s[e + 1] === "'") { t += "'"; j = e + 1; continue; }
        j = e; break;
      }
      add(t, true); i = j;
    } else if (c === '"') {
      let t = "", raw = "", j = i + 1;
      for (; j < s.length; j++) {
        if (s[j] === '"') { if (ps && s[j + 1] === '"') { t += '"'; raw += '""'; j++; continue; } break; }
        if (s[j] === esc && (ps || '"\\$`\n'.includes(s[j + 1]))) { t += s[j + 1]; raw += s[j] + s[j + 1]; j++; }
        else if (s[j] === "$" && s[j + 1] === "(") { const e = closing(s, j + 2, "(", ")", esc); t += s.slice(j, e + 1); raw += s.slice(j, e + 1); j = e; }
        else if (!ps && s[j] === "`") { const e = s.indexOf("`", j + 1); if (e < 0) throw new Error("unclosed `"); t += s.slice(j, e + 1); raw += s.slice(j, e + 1); j = e; }
        else { t += s[j]; raw += s[j]; }
      }
      if (j >= s.length) throw new Error('unclosed "');
      substitutions(raw, nested, ps);
      add(t, true); i = j;
    } else if ((c === "$" || (ps && c === "@")) && s[i + 1] === "(") {
      const e = closing(s, i + 2, "(", ")", esc); nested.push({ text: s.slice(i + 2, e), ps }); add(s.slice(i, e + 1), false); i = e;
    } else if (!ps && c === "`") { const e = s.indexOf("`", i + 1); if (e < 0) throw new Error("unclosed `"); nested.push({ text: s.slice(i + 1, e), ps }); add(s.slice(i, e + 1), false); i = e; }
    else if (!ps && (c === "<" || c === ">") && s[i + 1] === "(") { const e = closing(s, i + 2, "(", ")", esc); nested.push({ text: s.slice(i + 2, e), ps }); flush(); i = e; }
    else if (c === "<" || c === ">") {
      if (word && !word.quoted && (/^\d+$/.test(word.text) || (ps && word.text === "*"))) word = null; // 2>&1, *>: the stream is not a word
      flush();
      const op = s.slice(i).match(/^(<<-|<<<|<<|<>|>>|>\||[<>]&?|&?>>?)/)[0];
      i += op.length - 1;
      if (!ps && (op === "<<" || op === "<<-")) {
        const m = s.slice(i + 1).match(/^[ \t]*(?:'([^']*)'|"([^"]*)"|\\?([^\s;&|<>()]+))/);
        if (!m) throw new Error("heredoc without delimiter");
        heredocs.push({ delim: m[1] ?? m[2] ?? m[3], quoted: m[1] !== undefined || m[2] !== undefined || m[0].includes("\\"), tabs: op === "<<-" });
        i += m[0].length;
      } else redir = true;
    } else if (!ps && c === "&" && s[i + 1] === ">") { flush(); i += s[i + 2] === ">" ? 2 : 1; redir = true; }
    else if (c === "|" && s[i + 1] === "|") { end(); i++; }
    else if (c === "|") { end(true); if (s[i + 1] === "&") i++; }
    else if (";&|()".includes(c) || (ps && "{}".includes(c))) end();
    else add(c, false);
  }
  end();
  return cmds;
}

function readShell(s, depth, ps, ctx) {
  if (++ctx.reads > MAX_READS) throw new TooComplex("too many nested scripts");
  const nested = [], bodies = [];
  const out = [];
  for (let w of tokenize(s, ps, nested, bodies)) {
    while (w.length && !w[0].quoted && (ps ? ["&", "."].includes(w[0].text) : KEYWORDS.has(w[0].text))) w = w.slice(1);
    if (!w.length) continue;
    const piped = w.piped;
    w.ps = ps;
    w.piped = piped;
    out.push(w);
    const rest = (k) => w.slice(k).map((x) => x.text).join(" ");
    for (let k = 0; k < w.length; k++) {
      const name = programName(w[k].text);
      if (SHELLS.has(name)) {
        const c = w.findIndex((x, j) => j > k && /^-[a-z]*c[a-z]*$/i.test(x.text));
        if (c > 0 && w[c + 1]) nested.push({ text: w[c + 1].text, ps: false });
      } else if (POWERSHELLS.has(name)) {
        // Every argument may be the script (-Command, or positional for powershell.exe); an encoded one is decoded.
        nested.push({ text: rest(k + 1), ps: true });
        for (let j = k + 1; j < w.length - 1; j++) {
          if (/^[-/](e|ec|en[a-z]*)$/i.test(w[j].text)) nested.push({ text: decodeEncodedCommand(w[j + 1].text), ps: true });
        }
      } else if (name === "cmd" && w.slice(k + 1).some((x) => /^\/[ck]$/i.test(x.text))) {
        nested.push({ text: rest(w.findIndex((x, j) => j > k && /^\/[ck]$/i.test(x.text)) + 1), ps: true });
      }
    }
    const head = programName(w[commandStart(w)].text);
    if (head === "eval" || head === "watch") nested.push({ text: rest(commandStart(w) + 1), ps });
    if (["invoke-expression", "iex", "start-process", "saps", "start", "invoke-command", "icm"].includes(head)) {
      nested.push({ text: rest(commandStart(w) + 1), ps: true });
      // Start-Process npm -ArgumentList 'run deploy' runs `npm run deploy`.
      nested.push({ text: w.slice(commandStart(w) + 1).filter((x) => !/^-/.test(x.text)).map((x) => x.text.replace(/,/g, " ")).join(" "), ps: true });
    }
    if (head === "ssh") for (let k = 1; k < w.length; k++) nested.push({ text: rest(k), ps });
  }
  // A shell reading its script from stdin (`bash <<EOF`, `cat x | sh`, `bash <<< "..."`,
  // `"..." | pwsh -Command -`) runs whatever the line feeds it: heredoc bodies and the other
  // commands' arguments become code.
  for (const w of out) {
    const k = commandStart(w), name = programName(w[k].text), args = w.slice(k + 1);
    const flagsOnly = args.every((x) => x.redir || x.text === "-" || /^-(?!c$|[a-z]*c$)/i.test(x.text) || (POWERSHELLS.has(name) && /^-(c|com\w*)$/i.test(x.text)));
    const stdinShell = SHELLS.has(name) ? flagsOnly && !args.some((x) => /^-[a-z]*c[a-z]*$/i.test(x.text))
      : POWERSHELLS.has(name) ? flagsOnly || args.some((x) => x.text === "-")
      : name === "cmd" ? !args.some((x) => /^\/[ck]$/i.test(x.text)) : false;
    if (!stdinShell) continue;
    const dialect = !SHELLS.has(name);
    for (const b of bodies) nested.push({ text: b, ps: dialect });
    for (const v of out) if (v !== w) nested.push({ text: v.slice(v[0].quoted ? 0 : 1).map((x) => x.text).join(" "), ps: dialect });
    for (const x of args) if (x.redir) nested.push({ text: x.text, ps: dialect });
  }
  ctx.chars += nested.reduce((sum, n) => sum + n.text.length, 0);
  if (ctx.chars > MAX_CHARS) throw new TooComplex("too much nested script text");
  // Each script is read once, so repeats (every suffix of `ssh a b c`) cost nothing deeper down.
  const fresh = nested.filter((n) => n.text.trim() && !ctx.seen.has(`${n.ps}:${n.text}`));
  for (const n of fresh) ctx.seen.add(`${n.ps}:${n.text}`);
  if (fresh.length && depth >= MAX_DEPTH) throw new TooComplex("scripts nested too deeply");
  for (const n of fresh) out.push(...readShell(n.text, depth + 1, n.ps, ctx));
  return out;
}

// Reads a command line as POSIX shell and, when `ps` is set, also as PowerShell, so a check sees
// every way the line could run. `failed` is set when a reading failed (an unclosed quote, say);
// callers then also check the raw text, so they fail closed. `complex` is set when the line is past
// the reader's limits; callers refuse it outright.
export function shellCommands(command, { ps = false } = {}) {
  const cmds = [];
  let failed = false, complex = false;
  for (const dialect of ps ? [false, true] : [false]) {
    try { cmds.push(...readShell(String(command), 0, dialect, { seen: new Set(), reads: 0, chars: 0 })); } catch (e) { failed = true; if (e instanceof TooComplex) complex = true; }
  }
  return { cmds, failed, complex };
}

// A command guard matches where a command, or a path to the program it runs, starts: at its first
// word, at an unquoted later word (`sudo npm run deploy`, `bash scripts/release.sh`), or after a `/`
// in one (`./scripts/release.sh`). A match that starts inside a quoted argument (a commit message,
// a grep pattern) is data, not a command. PowerShell is matched without regard to case, as it runs
// commands. A line the reader cannot parse is also matched as plain text.
export function guardMatches(pattern, command, { ps = false } = {}) {
  const { cmds, failed, complex } = shellCommands(command, { ps });
  if (complex || (failed && commandMatches(pattern, command))) return true;
  const re = pattern.match(/^\/(.+)\/([a-z]*)$/);
  for (const w of cmds) {
    if (["echo", "printf", "write-output", "write-host"].includes(programName(w[0].text))) continue;
    const sticky = re && new RegExp(re[1], re[2].replace(/[gy]/g, "") + (w.ps && !re[2].includes("i") ? "iy" : "y"));
    const lit = pattern.replace(/\s+/g, " ").trim();
    const norm = (t) => (w.ps ? t.toLowerCase() : t);
    const text = w.map((x) => x.text.replace(/\\/g, w.ps ? "/" : "\\")).join(" ");
    let at = 0;
    for (const [k, x] of w.entries()) {
      if (!x.redir && (k === 0 || (!x.quoted && !/\s/.test(x.text)))) {
        for (let j = 0; j < x.text.length; j++) {
          if (j > 0 && !"/\\".includes(x.text[j - 1])) continue;
          const rest = text.slice(at + j);
          if (sticky ? (sticky.lastIndex = 0, sticky.test(rest)) : norm(rest).startsWith(norm(lit))) return true;
        }
      }
      at += x.text.length + 1;
    }
  }
  return false;
}

// Path globs relative to the project root: ** spans directories, * and ? stay within one.
export function globToRegExp(glob) {
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*" && glob[i + 1] === "*") {
      if (glob[i + 2] === "/") { re += "(?:.*/)?"; i += 2; } else { re += ".*"; i += 1; }
    } else if (c === "*") re += "[^/]*";
    else if (c === "?") re += "[^/]";
    else re += c.replace(/[.+^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp(`^${re}$`);
}

// ---------- bindings: what makes a skill reusable across repositories ----------
// A skill names project-specific values (commands, paths, globs, URLs, branch names) only through
// bindings: `${name}`, declared with a description in the skill's bindings.md and given a value per
// project in <root>/.flow/<skill>/project.md. The skill itself stays the same in every repository.
export const BINDING_RE = /\$\{([a-z][a-z0-9_-]*)\}/g;
export const PROJECT_FILE = "project.md";
export const bindingNames = (text) => new Set([...String(text).matchAll(BINDING_RE)].map((m) => m[1]));
export const projectFile = (root, skillName) => path.join(root, ".flow", skillName, PROJECT_FILE);

// A binding's value as a list of strings; an empty string or list means unbound.
const valueList = (v) => (v === undefined || v === null ? [] : (Array.isArray(v) ? v : [v]).map(String).filter((x) => x.trim() !== ""));

// The project's values: { values: Map(name -> string[]), problems }. Missing file -> empty map.
export function readProject(file) {
  if (!fs.existsSync(file)) return { values: new Map(), problems: [], exists: false };
  const { data, problems } = parseFrontmatter(fs.readFileSync(file, "utf8"));
  const values = new Map();
  for (const [k, v] of Object.entries(data || {})) if (valueList(v).length) values.set(k, valueList(v));
  return { values, problems: data ? problems : [...problems, "missing YAML frontmatter"], exists: true };
}

const reEscape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// Resolve one string. Prose joins list values with ", "; inside a /regex/ pattern each value is
// escaped and a list becomes an alternation. Unbound names are left as they are and reported.
export function resolveText(text, values, missing = new Set()) {
  const re = String(text).match(/^\/(.+)\/([a-z]*)$/);
  const sub = (s, regex) => s.replace(BINDING_RE, (m, name) => {
    const v = values.get(name);
    if (!v) { missing.add(name); return m; }
    return regex ? (v.length > 1 ? `(?:${v.map(reEscape).join("|")})` : reEscape(v[0])) : v.join(", ");
  });
  return re ? `/${sub(re[1], true)}/${re[2]}` : sub(String(text), false);
}

// Resolve a rails list (checks, writes, irreversible). An entry that mentions a list binding
// becomes one entry per value, so `${code}/**` with code [src, test] gives src/** and test/**.
export function resolveList(list, values, missing = new Set()) {
  const out = [];
  for (const entry of list) {
    if (/^\/.+\/[a-z]*$/.test(entry)) { out.push(resolveText(entry, values, missing)); continue; }
    let parts = [entry];
    for (const name of bindingNames(entry)) {
      const v = values.get(name);
      if (!v) { missing.add(name); continue; }
      parts = parts.flatMap((p) => v.map((x) => p.split(`\${${name}}`).join(x)));
    }
    out.push(...parts);
  }
  return out;
}

// Text that only fits one repository: paths (./x, ../x, ~/x, /x, dir/, a/b.ext, globs) and URLs.
// Paths that exist inside the skill itself (scripts/flow.mjs, playbooks/x.md) and the runtime's
// .flow/ directory are fine; so are bindings and <placeholders>.
export function repoSpecific(text, skillDir, baseDir = skillDir) {
  const hits = new Set();
  for (const raw of String(text).split(/[\s`"'()[\],;|]+/)) {
    const t = raw.replace(/^\*\*(?=\S)/, "").replace(/[.:!?]+$/, "");
    if (!/\w/.test(t) || /[<>]|\$\{|\{\{|\}\}/.test(t)) continue;
    if (/^https?:\/\//i.test(t)) { hits.add(t); continue; }
    if (!t.includes("/") || /^[a-z][a-z0-9+.-]*:/i.test(t)) continue;
    const pathish = /^(\.{1,2}|~)?\/[\w.@*-]/.test(t) || /\/\**$/.test(t) || t.includes("*") || /\/[\w@-][\w@.-]*\.[a-z][a-z0-9]{0,5}$/i.test(t);
    if (!pathish) continue;
    const rel = t.split("#")[0];
    if (/^\.flow(\/|$)/.test(rel)) continue;
    const inSkill = (d) => d && !path.isAbsolute(rel) && !rel.startsWith("~") && fs.existsSync(path.join(d, rel.replace(/\/\*+$/, "")));
    if (inSkill(skillDir) || inSkill(baseDir)) continue;
    hits.add(t);
  }
  return [...hits];
}

// ---------- minimal frontmatter parser ----------
// Supports the restricted YAML subset vajra emits and reports everything else as a
// problem instead of guessing:
//   key: scalar                 key: [a, b]            key: "quoted # not a comment"
//   key: >                      key:                   key:
//     folded text                 - k: v                 nested: scalar
//                                   k2: >
//                                     folded text
//                                 - plain item
// Plain scalars may continue on more-indented lines; ` #` starts a comment in plain scalars.
const KV = /^([A-Za-z0-9_-]+):(?:\s+(.*))?$/;
const BLOCK = /^[>|][+-]?$/;

function scalar(v) {
  v = v.trim();
  if (v === "") return "";
  const q = v[0];
  if (q === '"' || q === "'") {
    const close = v.indexOf(q, 1);
    if (close > 0) return v.slice(1, close);
  }
  v = v.replace(/\s+#.*$/, "");
  if (v === "true") return true;
  if (v === "false") return false;
  if (/^-?\d+(\.\d+)?$/.test(v)) return Number(v);
  if (v.startsWith("[") && v.endsWith("]")) {
    const inner = v.slice(1, -1).trim();
    return inner === "" ? [] : inner.split(",").map((s) => scalar(s));
  }
  return v;
}

export function parseFrontmatter(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---[ \t]*(?:\r?\n|$)/);
  if (!m) return { data: null, body: text, problems: [] };
  const lines = m[1].split(/\r?\n/);
  const problems = [];
  const bad = (i, why) => problems.push(`frontmatter line ${i + 2}: ${why}: "${lines[i].trim().slice(0, 60)}"`);

  const entries = [];
  lines.forEach((l, i) => {
    if (l.trim() === "" || /^\s*#/.test(l)) return;
    const lead = l.match(/^\s*/)[0];
    if (lead.includes("\t")) { bad(i, "tabs are not allowed for indentation"); return; }
    entries.push({ i, ind: lead.length, t: l.trim() });
  });

  const start = (key, v, i) => (BLOCK.test(v) ? { key, i, mode: v[0], parts: [] } : { key, i, mode: v === "" ? "empty" : "plain", parts: v === "" ? [] : [v] });
  const finish = (p, nested) => {
    if (p.mode === "|") return p.parts.map((x) => x.t).join("\n");
    if (p.mode === ">") return p.parts.map((x) => x.t).join(" ");
    if (p.mode === "empty") return p.parts.length ? nested(p) : "";
    return p.parts.length === 1 ? scalar(p.parts[0]) : p.parts.map((x) => (typeof x === "string" ? x : x.t)).join(" ");
  };

  function readMap(group, keyCol, where, allowNested) {
    const obj = {};
    let pend = null;
    const nested = (p) => {
      if (!allowNested) { bad(p.i, `nested structure under "${p.key}" is not supported`); return ""; }
      const first = p.parts[0];
      return /^-(\s|$)/.test(first.t) ? readList(p.parts) : readMap(p.parts, first.ind, `"${p.key}"`, false);
    };
    const flush = () => { if (pend) { obj[pend.key] = finish(pend, nested); pend = null; } };
    for (const e of group) {
      const kv = e.t.match(KV);
      if (e.ind === keyCol && kv) {
        flush();
        if (Object.hasOwn(obj, kv[1])) bad(e.i, `duplicate key "${kv[1]}"`);
        pend = start(kv[1], (kv[2] ?? "").trim(), e.i);
      } else if (pend && e.ind > keyCol) {
        pend.parts.push(e);
      } else bad(e.i, `not understood in ${where}`);
    }
    flush();
    return obj;
  }

  function readList(group) {
    const dash = group[0].ind;
    const items = [];
    let cur = null;
    const close = () => {
      if (!cur) return;
      if (cur.map) items.push(readMap(cur.lines, cur.keyCol ?? 0, "list item", false));
      else items.push(cur.lines.length ? [cur.value, ...cur.lines.map((e) => e.t)].join(" ") : scalar(cur.value));
      cur = null;
    };
    for (const e of group) {
      if (e.ind === dash && /^-(\s|$)/.test(e.t)) {
        close();
        const after = e.t.slice(1).trimStart();
        const col = e.ind + (e.t.length - after.length);
        if (after === "") cur = { map: true, lines: [], keyCol: null };
        else if (KV.test(after) && !/^["']/.test(after)) cur = { map: true, lines: [{ i: e.i, ind: col, t: after }], keyCol: col };
        else cur = { map: false, value: after, lines: [] };
      } else if (cur && e.ind > dash) {
        if (cur.map && cur.keyCol === null) cur.keyCol = e.ind;
        cur.lines.push(e);
      } else bad(e.i, "expected a `- ` list item");
    }
    close();
    return items;
  }

  // Top level: every entry at indent 0 must be `key: ...`.
  const top = [];
  for (const e of entries) {
    if (e.ind === 0 && !KV.test(e.t)) { bad(e.i, "expected `key: value` at the top level"); continue; }
    top.push(e);
  }
  const data = readMap(top, 0, "the top level", true);
  problems.sort((a, b) => parseInt(a.slice(17)) - parseInt(b.slice(17)));
  return { data, body: text.slice(m[0].length), problems };
}

function sections(body) {
  const out = new Map();
  let current = null;
  for (const line of body.split(/\r?\n/)) {
    const h = line.match(/^##\s+(.+?)\s*$/);
    if (h) { current = h[1]; out.set(current, []); continue; }
    if (current) out.get(current).push(line);
  }
  return out;
}

// ---------- playbook ----------
// Validate one playbook file on its own (no graph context). Used by validateSkill and by the
// blueprint tests.
export function validatePlaybook(text, id, where = `playbooks/${id}.md`, skillDir = null) {
  const errors = [];
  const warnings = [];
  const err = (msg) => errors.push(`${where}: ${msg}`);
  const warn = (msg) => warnings.push(`${where}: ${msg}`);

  const { data, body, problems } = parseFrontmatter(text);
  for (const p of problems) err(p);
  if (!data) { err("missing YAML frontmatter"); return { node: null, errors, warnings }; }
  for (const k of Object.keys(data)) if (!PLAYBOOK_KEYS.includes(k)) warn(`unknown frontmatter key "${k}"`);
  if (data.id !== id) err(`frontmatter id "${data.id}" must equal file name "${id}"`);

  const secs = sections(body);
  const stepLines = (secs.get("Steps") || []).filter((l) => /^\s*(\d+\.|-)\s/.test(l));
  const steps = (secs.get("Steps") || []).filter((l) => /^\d+\.\s/.test(l)).map((l, i) => ({
    n: i + 1,
    text: l.replace(/^\d+\.\s+/, "").trim(),
    humanGate: /\[human-gate\]/i.test(l),
    irreversible: /\[irreversible\]/i.test(l),
  }));
  const node = {
    id,
    title: data.title || id,
    phase: data.phase,
    lifecycle: data.lifecycle,
    kind: data.kind || "work",
    promotes: null,
    terminal: data.terminal === true,
    exits: Array.isArray(data.exits) ? data.exits : [],
    humanGates: stepLines.filter((l) => /\[human-gate\]/i.test(l)).length,
    irreversibleSteps: stepLines.filter((l) => /\[irreversible\]/i.test(l)).length,
    steps,
    doneWhen: (secs.get("Done when") || []).join("\n").trim(),
    checks: [],
    writes: [],
    guards: [],
  };

  if (!PHASES.includes(node.phase)) err(`phase must be one of ${PHASES.join("|")}`);
  if (!LIFECYCLES.includes(node.lifecycle)) err(`lifecycle must be one of ${LIFECYCLES.join("|")}`);
  if (!KINDS.includes(node.kind)) err(`kind must be one of ${KINDS.join("|")}`);
  if ((node.phase === "explore" && node.lifecycle === "hardened") || (node.phase === "extract" && node.lifecycle === "throwaway")) {
    warn(`phase ${node.phase} with lifecycle ${node.lifecycle} is unusual; check both`);
  }

  if (data.promotes !== undefined) {
    const pm = String(data.promotes).match(PROMOTES_RE);
    if (node.kind !== "gate") err("only gate playbooks (kind: gate) may declare `promotes`");
    else if (!pm) err('promotes must look like "throwaway->tracer"');
    else if (LIFECYCLE_RANK[pm[2]] <= LIFECYCLE_RANK[pm[1]]) err(`promotes ${pm[1]}->${pm[2]} does not raise the lifecycle`);
    else node.promotes = [pm[1], pm[2]];
  }
  if (node.kind === "gate" && !node.promotes && data.promotes === undefined && node.humanGates === 0) {
    warn("gate neither promotes a lifecycle nor stops at a [human-gate]; make it a work playbook or give it a job");
  }

  // rails: machine checks for "Done when", allowed write paths, and guarded irreversible commands
  const strList = (key) => {
    const v = data[key];
    if (v === undefined) return [];
    if (!Array.isArray(v) || v.some((x) => typeof x !== "string" || x.trim() === "")) { err(`\`${key}\` must be a list of non-empty strings`); return []; }
    return v;
  };
  node.checks = strList("checks");
  node.writes = strList("writes");
  node.guards = strList("irreversible");
  // Rails values differ per repository, so they come from the project through bindings.
  for (const [key, list] of [["checks", node.checks], ["writes", node.writes], ["irreversible", node.guards]]) {
    for (const x of list) if (!bindingNames(x).size) err(`\`${key}\` entry \`${x}\` is a literal; rails values belong to the project: write \`\${name}\` and declare name in bindings.md`);
  }
  // Check patterns against step text with every binding standing for itself.
  const self = { get: (name) => [`\${${name}}`] };
  for (const g of node.guards) {
    try { commandMatches(resolveText(g, self), ""); } catch { err(`irreversible pattern ${g} is not a valid regular expression`); }
  }
  if (node.guards.length && node.irreversibleSteps === 0) err("declares `irreversible` commands but has no [irreversible] step");
  for (const g of node.guards) {
    let hit = false;
    try { hit = steps.some((s) => s.irreversible && commandMatches(resolveText(g, self), s.text)); } catch { hit = true; }
    if (node.irreversibleSteps && !hit) warn(`irreversible pattern \`${g}\` appears in no [irreversible] step; name the command in the step so the runtime knows which gate guards it`);
  }

  if (data.exits !== undefined && !Array.isArray(data.exits)) err("exits must be a list");
  if (!node.terminal && node.exits.length === 0) err("non-terminal playbook needs at least one exit");
  for (const [n, e] of node.exits.entries()) {
    if (!e || typeof e !== "object" || !e.to) err(`exit #${n + 1} needs \`to\``);
    else if (typeof e.when !== "string" || e.when.trim() === "") err(`exit to "${e.to}" needs a \`when\` condition`);
    if (e && e.on !== undefined && !["pass", "fail"].includes(e.on)) err(`exit to "${e.to}": \`on\` must be pass or fail`);
  }
  if (node.exits.some((e) => e && e.on) && node.checks.length === 0) err("exits use `on` but the playbook has no `checks`");

  for (const s of REQUIRED_SECTIONS) {
    if (!secs.has(s)) err(`missing "## ${s}" section`);
    else if (secs.get(s).every((l) => l.trim() === "")) err(`"## ${s}" section is empty`);
  }
  if (secs.has("Steps") && stepLines.length === 0) err('"## Steps" has no numbered steps');

  // irreversible steps need a human gate earlier in the same playbook (or on the same step)
  let gated = false;
  for (const l of stepLines) {
    if (/\[human-gate\]/i.test(l)) gated = true;
    if (/\[irreversible\]/i.test(l) && !gated) err(`irreversible step without a preceding [human-gate]: "${l.trim().slice(0, 80)}"`);
  }
  if (stepLines.length > 12) warn(`${stepLines.length} steps; consider splitting the playbook`);
  if (skillDir) {
    const hits = repoSpecific(body, skillDir, path.join(skillDir, "playbooks"));
    if (hits.length) warn(`${hits.map((h) => `\`${h}\``).join(", ")} ${hits.length > 1 ? "look" : "looks"} repository-specific; use a binding (\`\${name}\` declared in bindings.md) so the skill works in any repository`);
  }
  node.bindings = [...bindingNames(text.slice(0, text.length - body.length)), ...bindingNames(body)];
  return { node, errors, warnings };
}

// ---------- profile ----------
function readProfile(dir, err, warn) {
  const where = "profile.md";
  const p = path.join(dir, "profile.md");
  if (!fs.existsSync(p)) { warn(where, "missing; profile-to-graph consistency checks skipped"); return null; }
  const { data, body, problems } = parseFrontmatter(fs.readFileSync(p, "utf8"));
  for (const pr of problems) err(where, pr);
  if (!data) {
    err(where, `no frontmatter; schema ${SCHEMA} keeps the profile axes there (see references/graph-model.md#schema-versions)`);
    return null;
  }
  if (data.schema === undefined) err(where, "frontmatter `schema` is required");
  else if (typeof data.schema !== "number") err(where, "`schema` must be a number");
  else if (data.schema > SCHEMA) err(where, `written for schema ${data.schema}; this validator (vajra ${VERSION}) supports schema ${SCHEMA}. Update vajra`);
  else if (data.schema < SCHEMA) err(where, `schema ${data.schema} is outdated; run vajra Evolve to migrate to schema ${SCHEMA}`);
  if (!data.generator) warn(where, "frontmatter `generator` is missing (expected vajra@<version>)");
  for (const [axis, values] of Object.entries(PROFILE_AXES)) {
    const v = data[axis];
    if (v === undefined || v === "") { warn(where, `axis \`${axis}\` is missing`); continue; }
    if (LIST_AXES.has(axis)) {
      if (!Array.isArray(v)) { err(where, `\`${axis}\` must be a list like [a, b]`); continue; }
      for (const x of v) {
        if (values ? !values.includes(x) : !(typeof x === "string" && NAME_RE.test(x))) {
          err(where, `\`${axis}\` value "${x}" must be ${values ? `one of ${values.join("|")}` : "lowercase-hyphenated"}`);
        }
      }
      if (axis === "journey" && v.length === 0) err(where, "`journey` needs at least one phase");
    } else if (!values.includes(v)) err(where, `\`${axis}\` must be one of ${values.join("|")}`);
  }
  const model = sections(body).get("Domain model");
  if (!model || model.every((l) => l.trim() === "")) warn(where, "no `## Domain model` section; describe this domain's areas, evidence ladder and irreversible actions in concrete terms");
  return data;
}

// Rules from references/composition.md that can be checked mechanically. Generated skills may
// deviate on purpose, so these are warnings; the reason belongs in profile.md "Composition notes".
function checkComposition(profile, skillFm, nodes, err, warn) {
  const list = [...nodes.values()];
  const promotes = list.filter((n) => n.promotes).map((n) => n.promotes);
  const lifecycles = new Set(list.map((n) => n.lifecycle));
  const journey = new Set(Array.isArray(profile.journey) ? profile.journey : []);
  const where = "profile.md";

  if (profile.invocation === "explicit" && skillFm?.description && !/\binvoke|\bby name\b|\bexplicitly\b/i.test(skillFm.description)) {
    warn("SKILL.md", "profile invocation is explicit but the description does not say to run only when invoked by name");
  }
  if (journey.size) {
    if (journey.has("explore") && (journey.has("expand") || journey.has("extract")) && !promotes.some(([f]) => f === "throwaway")) {
      warn(where, "journey leaves explore but no gate promotes from throwaway");
    }
    if (journey.has("extract") && !promotes.some(([, t]) => t === "hardened")) warn(where, "journey includes extract but no gate promotes to hardened");
    if (!journey.has("extract") && lifecycles.has("hardened")) warn(where, "hardened playbooks exist but journey lacks extract");
    if (!journey.has("explore") && lifecycles.has("throwaway")) warn(where, "throwaway playbooks exist but journey lacks explore");
  }
  if (profile.failure_cost === "regulated") {
    for (const n of list) if (n.promotes && n.humanGates === 0) warn(`playbooks/${n.id}.md`, "failure_cost is regulated; every promotion gate needs a [human-gate] step");
  }
  const facets = new Set(Array.isArray(profile.facets) ? profile.facets : []);
  const rails = profile.rails;
  if (rails && rails !== "advisory") {
    for (const n of list) if (n.irreversibleSteps > 0 && n.guards.length === 0) warn(`playbooks/${n.id}.md`, "has [irreversible] steps but declares no `irreversible` command patterns, so the hooks cannot block them");
  }
  if (profile.hardware && profile.hardware !== "none" && !facets.has("physical-world")) warn(where, `hardware is ${profile.hardware} but facets lack physical-world`);
  if (facets.has("physical-world") && rails === "advisory") warn(where, "physical-world needs rails: standard or strict");
  if (profile.failure_cost === "regulated" && rails && rails !== "strict") warn(where, "failure_cost is regulated; use rails: strict");
  if (["test-after", "tdd", "formal"].includes(profile.verification)) {
    for (const n of list) {
      if (n.kind === "work" && ["tracer", "hardened"].includes(n.lifecycle) && n.checks.length === 0) {
        warn(`playbooks/${n.id}.md`, `verification is ${profile.verification} but this kept-code playbook has no \`checks\``);
      }
    }
  }
  const anyIrreversible = list.some((n) => n.irreversibleSteps > 0);
  if (profile.hardware && profile.hardware !== "none" && !anyIrreversible) warn(where, `hardware is ${profile.hardware} but no step is tagged [irreversible]`);
  if (journey.has("extract") && ["customer", "regulated"].includes(profile.failure_cost) && !anyIrreversible) {
    warn(where, "journey reaches production for customers but no step is tagged [irreversible] (deploys, migrations)");
  }
}

// ---------- skill ----------
export function validateSkill(dir, { project } = {}) {
  const errors = [];
  const warnings = [];
  const err = (where, msg) => errors.push(`${where}: ${msg}`);
  const warn = (where, msg) => warnings.push(`${where}: ${msg}`);
  const empty = { ok: false, errors, warnings, nodes: [], edges: [], entries: [], profile: null, bindings: {}, project: null };

  const skillPath = path.join(dir, "SKILL.md");
  if (!fs.existsSync(skillPath)) { err("SKILL.md", "missing"); return empty; }
  const skillText = fs.readFileSync(skillPath, "utf8");
  const { data: fm, body: skillBody, problems } = parseFrontmatter(skillText);
  for (const p of problems) err("SKILL.md", p);
  const dirName = path.basename(path.resolve(dir));
  // The router is a plain Agent Skills skill, so any agent that implements the spec can load it.
  if (!fm) err("SKILL.md", "missing YAML frontmatter");
  else {
    for (const k of Object.keys(fm)) {
      if (!SKILL_FIELDS.includes(k)) err("SKILL.md", `frontmatter field \`${k}\` is not in the Agent Skills specification (${SKILL_FIELDS.join(", ")}); keep harness-specific settings out of the skill`);
    }
    if (!fm.name) err("SKILL.md", "frontmatter `name` is required");
    else {
      if (!NAME_RE.test(fm.name) || fm.name.length > 64) err("SKILL.md", `name "${fm.name}" must be 1-64 lowercase letters, digits and single hyphens`);
      if (fm.name !== dirName) err("SKILL.md", `name "${fm.name}" must match the directory name "${dirName}"`);
    }
    if (!fm.description) err("SKILL.md", "frontmatter `description` is required");
    else if (String(fm.description).length > 1024) err("SKILL.md", "description exceeds 1024 characters");
    if (fm.compatibility !== undefined && (typeof fm.compatibility !== "string" || fm.compatibility.length < 1 || fm.compatibility.length > 500)) err("SKILL.md", "`compatibility` must be 1-500 characters");
    if (fm.metadata !== undefined && (typeof fm.metadata !== "object" || Array.isArray(fm.metadata) || Object.values(fm.metadata).some((v) => typeof v !== "string"))) {
      err("SKILL.md", "`metadata` must map string keys to string values (quote numbers)");
    }
    if (fm["allowed-tools"] !== undefined && typeof fm["allowed-tools"] !== "string") err("SKILL.md", "`allowed-tools` must be a space-separated string");
  }
  const skillLines = skillText.split(/\r?\n/).length;
  if (skillLines > 500) warn("SKILL.md", `${skillLines} lines; keep the router under 500 lines and move detail into playbooks`);

  const profile = readProfile(dir, err, warn);

  // playbooks
  const pbDir = path.join(dir, "playbooks");
  const files = fs.existsSync(pbDir) ? fs.readdirSync(pbDir).filter((f) => f.endsWith(".md")).sort() : [];
  if (files.length === 0) err("playbooks/", "no playbooks found");
  const nodes = new Map();
  for (const f of files) {
    const id = f.replace(/\.md$/, "");
    const r = validatePlaybook(fs.readFileSync(path.join(pbDir, f), "utf8"), id, undefined, dir);
    errors.push(...r.errors);
    warnings.push(...r.warnings);
    if (r.node) nodes.set(id, r.node);
  }

  // edges
  const edges = [];
  for (const node of nodes.values()) {
    for (const e of node.exits) {
      if (!e || !e.to) continue;
      if (e.to === "end") { edges.push({ from: node.id, to: "end", when: e.when }); continue; }
      if (!nodes.has(e.to)) { err(`playbooks/${node.id}.md`, `exit target "${e.to}" does not exist`); continue; }
      edges.push({ from: node.id, to: e.to, when: e.when });
    }
  }
  const out = new Map([...nodes.keys()].map((k) => [k, []]));
  for (const e of edges) if (e.to !== "end") out.get(e.from).push(e.to);

  // Lifecycle raises must pass through a gate that declares the raise (`promotes: from->to`).
  // Walk from every node that fixes a lifecycle level; `any` nodes and gates without `promotes`
  // are transparent, so detours through service playbooks are caught too.
  const walk = (src, level) => {
    const visited = new Set([src.id]);
    const queue = [...out.get(src.id)];
    while (queue.length) {
      const id = queue.shift();
      if (visited.has(id)) continue;
      visited.add(id);
      const t = nodes.get(id);
      if (t.promotes) {
        const from = LIFECYCLE_RANK[t.promotes[0]];
        if (level < from) err(`playbooks/${src.id}.md`, `path to gate "${id}" arrives with ${RANK_NAME[level]} work, but the gate promotes from ${t.promotes[0]}`);
        continue;
      }
      const tr = LIFECYCLE_RANK[t.lifecycle];
      if (tr !== undefined) {
        if (tr > level) err(`playbooks/${src.id}.md`, `path to "${id}" raises lifecycle ${RANK_NAME[level]} -> ${t.lifecycle} without passing a gate that promotes it`);
        continue;
      }
      queue.push(...out.get(id));
    }
  };
  for (const n of nodes.values()) {
    if (n.promotes) walk(n, LIFECYCLE_RANK[n.promotes[1]]);
    else if (LIFECYCLE_RANK[n.lifecycle] !== undefined) walk(n, LIFECYCLE_RANK[n.lifecycle]);
  }

  // router: entries are playbooks the router links to
  const linked = new Set();
  for (const m of skillBody.matchAll(/playbooks\/([a-z0-9-]+)\.md/g)) linked.add(m[1]);
  for (const id of linked) if (!nodes.has(id)) err("SKILL.md", `routes to missing playbook "playbooks/${id}.md"`);
  const entries = [...linked].filter((id) => nodes.has(id));
  if (entries.length === 0 && nodes.size) err("SKILL.md", "router links to no playbooks");

  // reachability from router entries
  const seen = new Set(entries);
  const stack = [...entries];
  while (stack.length) for (const n of out.get(stack.pop())) if (!seen.has(n)) { seen.add(n); stack.push(n); }
  for (const id of nodes.keys()) if (!seen.has(id)) err(`playbooks/${id}.md`, "unreachable from the router (no route and no incoming exit)");

  // every node can reach an end (terminal or exit to end)
  const canEnd = new Set([...nodes.values()].filter((n) => n.terminal || n.exits.some((e) => e && e.to === "end")).map((n) => n.id));
  let changed = true;
  while (changed) {
    changed = false;
    for (const [id, outs] of out) if (!canEnd.has(id) && outs.some((o) => canEnd.has(o))) { canEnd.add(id); changed = true; }
  }
  for (const id of nodes.keys()) if (!canEnd.has(id)) err(`playbooks/${id}.md`, "cannot reach an end (trap cycle)");

  if (nodes.size > 15) warn("playbooks/", `${nodes.size} playbooks; vajra aims for 5-12 — prune what the profile does not need`);
  const levels = new Set([...nodes.values()].map((n) => n.lifecycle).filter((l) => l in LIFECYCLE_RANK));
  if (levels.size > 1 && ![...nodes.values()].some((n) => n.promotes)) warn("playbooks/", "multiple lifecycles but no gate declares `promotes`");

  // Domain fit: work and gate playbooks must speak in this domain's concrete terms.
  const anchor = /`[^`]+`|\]\(|\d/;
  for (const n of nodes.values()) {
    if (n.kind === "service") continue;
    if (n.doneWhen && !anchor.test(n.doneWhen)) warn(`playbooks/${n.id}.md`, '"Done when" names no concrete evidence (a command, path, metric or link); name what proves it in this domain');
    if (n.steps.length && !n.steps.some((s) => anchor.test(s.text))) warn(`playbooks/${n.id}.md`, "no step names a concrete command, tool or artifact; write the steps in this domain's terms");
  }

  // Runtime: generated skills carry their own copy of the rails.
  const rt = path.join(dir, "scripts", "flow.mjs");
  const rtLib = path.join(dir, "scripts", "validate.mjs");
  if (!fs.existsSync(rt) || !fs.existsSync(rtLib)) warn("scripts/", "runtime missing (flow.mjs, validate.mjs): nothing enforces the graph; copy them from vajra");
  else {
    const v = fs.readFileSync(rtLib, "utf8").match(/export const VERSION = "([^"]+)"/);
    if (!v || v[1] !== VERSION) warn("scripts/", `runtime is vajra ${v ? v[1] : "unknown"}, validator is ${VERSION}; run Evolve to update the runtime`);
    if (!/scripts\/flow\.mjs/.test(skillBody)) warn("SKILL.md", "router does not tell the agent to drive the run with scripts/flow.mjs");
  }

  if (profile) checkComposition(profile, fm, nodes, err, warn);

  // Portability: the skill names project-specific values only through bindings.
  const bindings = readBindings(dir, err, warn);
  const used = new Map();
  const use = (where, names) => { for (const n of names) if (!used.has(n)) used.set(n, where); };
  for (const n of nodes.values()) use(`playbooks/${n.id}.md`, n.bindings);
  const prose = [["SKILL.md", skillText]];
  for (const f of ["principles.md", "profile.md"]) if (fs.existsSync(path.join(dir, f))) prose.push([f, fs.readFileSync(path.join(dir, f), "utf8")]);
  for (const [where, text] of prose) {
    use(where, bindingNames(text));
    const hits = repoSpecific(text, dir);
    if (hits.length) warn(where, `${hits.map((h) => `\`${h}\``).join(", ")} ${hits.length > 1 ? "look" : "looks"} repository-specific; use a binding (\`\${name}\` declared in bindings.md) so the skill works in any repository`);
  }
  for (const [name, where] of used) if (!bindings.has(name)) err(where, `binding \`\${${name}}\` is not declared in bindings.md`);
  for (const name of bindings.keys()) if (!used.has(name)) warn("bindings.md", `\`${name}\` is declared but no file uses \`\${${name}}\``);

  // Optional: does a project bind every name?
  let projectResult = null;
  if (project) {
    // A project root, or the project file itself.
    const file = /\.md$/i.test(project) && fs.existsSync(project) && fs.statSync(project).isFile() ? project : projectFile(project, dirName);
    const where = path.relative(process.cwd(), file) || file;
    const p = readProject(file);
    for (const pr of p.problems) err(where, pr);
    if (!p.exists) err(where, `missing; bind ${[...bindings.keys()].join(", ") || "nothing"} there (\`flow install\` writes a skeleton)`);
    const missing = [...bindings.keys()].filter((n) => !p.values.has(n));
    if (p.exists && missing.length) err(where, `no value for ${missing.map((n) => `\`${n}\``).join(", ")}`);
    for (const k of p.values.keys()) if (!bindings.has(k)) warn(where, `\`${k}\` is not declared in the skill's bindings.md`);
    projectResult = { file, values: Object.fromEntries(p.values), missing };
  }

  const list = [...nodes.values()].map((n) => ({ ...n, promotes: n.promotes ? n.promotes.join("->") : null }));
  return { ok: errors.length === 0, errors, warnings, nodes: list, edges, entries, profile, bindings: Object.fromEntries(bindings), project: projectResult };
}

// bindings.md: `name: what the project must supply` in the frontmatter, one line per binding.
function readBindings(dir, err, warn) {
  const out = new Map();
  const file = path.join(dir, "bindings.md");
  if (!fs.existsSync(file)) return out;
  const { data, problems } = parseFrontmatter(fs.readFileSync(file, "utf8"));
  for (const pr of problems) err("bindings.md", pr);
  if (!data) { err("bindings.md", "missing YAML frontmatter (`name: what the project supplies`, one per binding)"); return out; }
  for (const [k, v] of Object.entries(data)) {
    if (!/^[a-z][a-z0-9_-]*$/.test(k)) err("bindings.md", `binding name "${k}" must be lowercase letters, digits, - and _, starting with a letter`);
    if (typeof v !== "string" || v.trim() === "") err("bindings.md", `\`${k}\` needs a one-line description of what the project supplies`);
    out.set(k, typeof v === "string" ? v : "");
  }
  return out;
}

// ---------- mermaid ----------
const esc = (s) => String(s).replace(/"/g, "#quot;").replace(/\|/g, "#124;");
const safe = (id) => id.replace(/-/g, "_");
const shorten = (s, n) => (s.length <= n ? s : s.slice(0, s.lastIndexOf(" ", n - 1) > 0 ? s.lastIndexOf(" ", n - 1) : n - 1) + "…");
const promoLabel = (p) => p.replace("->", " → ");

export function toMermaid(result) {
  const out = ["flowchart TD", "  router([router])"];
  const label = (n) => esc(n.promotes ? `${n.title} (${promoLabel(n.promotes)})` : n.title);
  const shape = (n) => (n.kind === "gate" ? `{{"${label(n)}"}}` : n.kind === "service" ? `[/"${label(n)}"/]` : `["${label(n)}"]`);
  for (const n of result.nodes) out.push(`  ${safe(n.id)}${shape(n)}`);
  if (result.edges.some((e) => e.to === "end")) out.push("  end_((end))");
  for (const id of result.entries) out.push(`  router --> ${safe(id)}`);
  for (const e of result.edges) {
    out.push(`  ${safe(e.from)} -->|"${esc(shorten(String(e.when), 48))}"| ${e.to === "end" ? "end_" : safe(e.to)}`);
  }
  const byLife = { throwaway: [], tracer: [], hardened: [] };
  for (const n of result.nodes) if (byLife[n.lifecycle]) byLife[n.lifecycle].push(safe(n.id));
  out.push("  classDef throwaway fill:#fde68a,stroke:#b45309,color:#000");
  out.push("  classDef tracer fill:#bfdbfe,stroke:#1d4ed8,color:#000");
  out.push("  classDef hardened fill:#bbf7d0,stroke:#15803d,color:#000");
  for (const [k, ids] of Object.entries(byLife)) if (ids.length) out.push(`  class ${ids.join(",")} ${k}`);
  return out.join("\n");
}

export function graphMarkdown(result, name) {
  const kind = (n) => (n.promotes ? `gate (${promoLabel(n.promotes)})` : n.kind);
  const rows = result.nodes.map((n) => `| [${n.id}](playbooks/${n.id}.md) | ${kind(n)} | ${n.phase} | ${n.lifecycle} | ${n.exits.map((e) => e.to).join(", ") || "-"} |`);
  return [
    `# ${name} workflow graph`,
    "",
    "Generated by `vajra/scripts/validate.mjs --write-graph`. Do not edit by hand; edit playbook frontmatter and regenerate.",
    "",
    "```mermaid",
    toMermaid(result),
    "```",
    "",
    "| Playbook | Kind | Phase | Lifecycle | Exits to |",
    "|---|---|---|---|---|",
    ...rows,
    "",
  ].join("\n");
}

// ---------- CLI ----------
const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const args = process.argv.slice(2);
  if (args.includes("--version")) {
    console.log(`vajra ${VERSION} (schema ${SCHEMA})`);
    process.exit(0);
  }
  const dir = args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--project");
  if (!dir) {
    console.error("usage: node validate.mjs <skill-dir> [--project <root>] [--mermaid] [--write-graph] [--json]");
    process.exit(2);
  }
  const pi = args.indexOf("--project");
  const result = validateSkill(dir, { project: pi >= 0 ? args[pi + 1] : undefined });
  let graphNote = "";
  if (args.includes("--write-graph")) {
    if (result.ok) fs.writeFileSync(path.join(dir, "graph.md"), graphMarkdown(result, path.basename(path.resolve(dir))));
    else graphNote = "graph.md not written: fix the errors first";
  }
  if (args.includes("--json")) {
    console.log(JSON.stringify(result, null, 2));
  } else {
    for (const e of result.errors) console.log(`ERROR   ${e}`);
    for (const w of result.warnings) console.log(`WARN    ${w}`);
    console.log(`${result.ok ? "OK" : "FAILED"}: ${result.nodes.length} playbooks, ${result.edges.length} edges, ${result.errors.length} errors, ${result.warnings.length} warnings`);
    if (graphNote) console.log(graphNote);
    if (args.includes("--mermaid")) console.log("\n" + toMermaid(result));
  }
  process.exit(result.ok ? 0 : 1);
}
